/* ===================== BÀI 13 · MOV, XCHG, LEA và chuyển dữ liệu ===================== */
/* Bài 13 · MOV, XCHG, LEA và chuyển dữ liệu (AMTS-EMB-002-M04-L01, X86-013) — sinh bởi tools/author/mpu8086/l13.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P13=[{"label": "Ví dụ: các dạng MOV hợp lệ", "code": "; Ví dụ 1: các dạng MOV hợp lệ và giá của từng dạng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DW      1234H                   ; nguồn\ny       DW      ?                       ; đích word\nb       DB      ?                       ; đích byte\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; thanh ghi ← số tức thời\n        MOV     DS, AX                  ; thanh ghi đoạn ← thanh ghi\n        MOV     BX, x                   ; thanh ghi ← bộ nhớ\n        MOV     CX, BX                  ; thanh ghi ← thanh ghi\n        MOV     y, CX                   ; bộ nhớ ← thanh ghi\n        MOV     b, 7FH                  ; bộ nhớ ← số tức thời\n        MOV     AX, x                   ; AX ← bộ nhớ: dạng ngắn A1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và nhìn phần Mã máy và chu kỳ: mỗi dạng MOV có mã lệnh riêng. MOV BX, x tốn 8 + 6 = 14 chu kỳ, 4 byte; MOV AX, x cùng việc nhưng dùng dạng ngắn A1: 10 chu kỳ, 3 byte. MOV b, 7Fh ghi hằng vào ô nhớ mà không cần thanh ghi (C6 06…, 16 chu kỳ). Xem y = 1234h, b = 7Fh ở phần Bộ nhớ. Đoán trước: sau MOV CX, BX, CX bằng bao nhiêu (hệ 16)? Đáp án 1234h."}, {"label": "Lỗi: chép thẳng ô nhớ sang ô nhớ", "code": "; Ví dụ 2 (lỗi cố ý): chép thẳng ô nhớ sang ô nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DW      1234H\ny       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     y, x                    ; 8086 không có dạng bộ nhớ ← bộ nhớ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: MOV y, x có hai toán hạng bộ nhớ. Trình dịch dừng ở dòng đó và gợi ý dùng thanh ghi trung gian. Bản sửa là Ví dụ 3."}, {"label": "Sửa: chép và đổi chỗ qua thanh ghi", "code": "; Ví dụ 3 (bản sửa): chép và đổi chỗ qua thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1111H\nb       DW      2222H\nc       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, a                   ; chép a sang c: đi qua AX\n        MOV     c, AX\n        MOV     AX, a                   ; đổi chỗ a và b: 3 lệnh\n        XCHG    AX, b                   ; AX nhận b, b nhận a\n        MOV     a, AX                   ; a nhận b cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bản sửa của Ví dụ 2. Chép a sang c bằng MOV AX, a / MOV c, AX (dạng A1, A3: 10 chu kỳ mỗi lệnh). Đổi chỗ a và b chỉ cần 3 lệnh: XCHG AX, b (87 06…, 17 + 6 = 23 chu kỳ) vừa ghi a cũ vào b vừa đưa b cũ về AX. Kết quả: a = 2222h, b = 1111h, c = 1111h. Đoán trước: sau XCHG AX, b, AX bằng bao nhiêu? Đáp án 2222h."}, {"label": "Ví dụ: XCHG giữa hai thanh ghi", "code": "; Ví dụ 4: XCHG giữa hai thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H\n        MOV     BX, 5678H\n        XCHG    AX, BX                  ; 1 byte (93h): AX = 5678h, BX = 1234h\n        MOV     DX, AX                  ; cách 3 lệnh MOV, DX trung gian:\n        MOV     AX, BX                  ; đổi lại AX và BX\n        MOV     BX, DX\n        MOV     CX, 0AB12H\n        XCHG    CL, CH                  ; đổi hai nửa của CX: 12ABh\n        NOP                             ; 90h, cũng là XCHG AX, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "XCHG AX, BX chỉ 1 byte (93h) và 3 chu kỳ; ba lệnh MOV qua DX tốn 6 byte, 6 chu kỳ để làm cùng việc (đổi lại như cũ). XCHG CL, CH đổi hai nửa của CX: AB12h thành 12ABh. NOP là byte 90h, chính là XCHG AX, AX. Đoán trước: sau XCHG CL, CH, CX bằng bao nhiêu? Đáp án 12ABh."}, {"label": "Ví dụ: LEA, OFFSET và địa chỉ có thanh ghi", "code": "; Ví dụ 5: LEA, OFFSET và địa chỉ có thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DW      0\nbang    DB      10H, 20H, 30H, 40H, 50H\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET bang         ; 3 byte, 4 chu kỳ\n        LEA     DI, bang                ; 4 byte, 2 + 6 = 8 chu kỳ\n        MOV     BX, 2\n        LEA     DX, [BX+SI+1]           ; DX = 2 + 2 + 1: chỉ tính địa chỉ\n        MOV     AL, [BX+SI+1]           ; AL = nội dung ô DS:0005h\n        MOV     kq, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Biến dem chiếm độ lệch 0000h–0001h nên bang ở 0002h: MOV SI, OFFSET bang và LEA DI, bang cho cùng giá trị 0002h nhưng LEA dài hơn 1 byte, chậm hơn 4 chu kỳ. LEA DX, [BX+SI+1] chỉ tính DX = 2 + 2 + 1 = 5, không đọc bộ nhớ; MOV AL, [BX+SI+1] đọc ô DS:0005h = 40h. Đoán trước: sau LEA DX, [BX+SI+1], DX bằng bao nhiêu? Đáp án 0005h."}, {"label": "Bẫy: MOV lấy nội dung, LEA lấy địa chỉ", "code": "; Ví dụ 6 (bẫy): MOV lấy nội dung, LEA lấy địa chỉ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DW      5\nso      DW      0ABCDH\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, so                  ; BX = nội dung của so = ABCDh\n        LEA     SI, so                  ; SI = địa chỉ của so = 0002h\n        MOV     AX, [SI]                ; đúng: AX = ABCDh\n        MOV     DX, [BX]                ; sai: đọc ô DS:ABCDh, không phải so\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: MOV BX, so nạp nội dung ABCDh, không phải địa chỉ. Dùng BX làm con trỏ (MOV DX, [BX]) là đọc ô DS:ABCDh, một vùng nhớ không liên quan (trên trình mô phỏng là 0, máy thật là giá trị bất kỳ); vì ABCDh lẻ nên lệnh còn tốn thêm 4 chu kỳ (17). LEA SI, so cho đúng địa chỉ 0002h và MOV AX, [SI] đọc đúng ABCDh. Đoán trước: sau LEA SI, so, SI bằng bao nhiêu? Đáp án 0002h."}, {"label": "Ví dụ: XLAT tra bảng chữ số hệ 16", "code": "; Ví dụ 7: XLAT tra bảng chữ số hệ 16\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhex     DB      '0123456789ABCDEF'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        LEA     BX, hex                 ; BX trỏ đầu bảng\n        MOV     AH, 02H                 ; hàm in ký tự\n        MOV     AL, 0CH                 ; giá trị 12\n        XLAT                            ; AL = byte ở DS:[BX + AL] = 'C'\n        MOV     DL, AL\n        INT     21H\n        MOV     AL, 7\n        XLAT                            ; AL = '7'\n        MOV     DL, AL\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "LEA BX, hex trỏ BX vào đầu bảng 16 ký tự. Với AL = 0Ch, XLAT đọc byte ở DS:[BX + 0Ch] là 'C' (43h); với AL = 7 được '7'. Màn hình in C7. XLAT chỉ 1 byte, 11 chu kỳ. Đoán trước: sau XLAT đầu tiên, AL bằng bao nhiêu (hệ 16)? Đáp án 43h."}, {"label": "Lỗi: nạp hằng thẳng vào DS", "code": "; Ví dụ 8 (lỗi cố ý): nạp hằng thẳng vào DS\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DB      5\n        .CODE\nMAIN    PROC\n        MOV     DS, @DATA               ; 8086 không có MOV sreg, số tức thời\n        MOV     AL, x\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: MOV DS, @DATA nạp hằng thẳng vào thanh ghi đoạn, 8086 không có dạng này. Sửa: MOV AX, @DATA rồi MOV DS, AX như mọi ví dụ khác."}];
const sim13=makeX86Sim(document.getElementById("x86-l13"),{id:"s13",presets:P13,file:"BAI13.ASM"});
makeX86Ex(document.getElementById("ex-l13"),sim13,[{"t": "Đổi chỗ hai phím", "d": "Đọc hai phím bằng INT 21h hàm 08h vào biến p và q (code mẫu đã làm). Đổi chỗ nội dung hai biến trong bộ nhớ (sau đó p chứa phím thứ hai, q chứa phím thứ nhất) rồi in p, q bằng INT 21h hàm 02h. 8086 không có MOV p, q: phải đi qua thanh ghi. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: đổi chỗ hai phím trong bộ nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\np       DB      ?                       ; phím thứ nhất\nq       DB      ?                       ; phím thứ hai\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     p, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     q, AL\n; Viết code ở đây: đổi chỗ nội dung p và q\n; (8086 không có MOV p, q)\n\n        MOV     AH, 02H                 ; in p rồi q\n        MOV     DL, p\n        INT     21H\n        MOV     DL, q\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB", "out": "BA", "mem": [{"at": "p", "bytes": [66]}, {"at": "q", "bytes": [65]}]}, {"in": "xy", "out": "yx", "mem": [{"at": "p", "bytes": [121]}, {"at": "q", "bytes": [120]}]}, {"in": "11", "out": "11", "mem": [{"at": "p", "bytes": [49]}, {"at": "q", "bytes": [49]}]}, {"in": "~ ", "out": " ~", "mem": [{"at": "p", "bytes": [32]}, {"at": "q", "bytes": [126]}]}, {"in": "$#", "out": "#$", "mem": [{"at": "p", "bytes": [35]}, {"at": "q", "bytes": [36]}]}, {"in": "Az", "out": "zA", "mem": [{"at": "p", "bytes": [122]}, {"at": "q", "bytes": [65]}]}]}, {"t": "Mã LED 7 đoạn", "d": "Bảng led7 cho mã đoạn của chữ số 0–9 (bit 0 là đoạn a, …, bit 6 là đoạn g; quy ước của đề). Đọc hai phím chữ số '0'–'9' bằng INT 21h hàm 08h; ghi mã đoạn của chữ số thứ nhất vào ma, của chữ số thứ hai vào ma+1. Dùng XLAT. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: mã LED 7 đoạn của hai chữ số\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\n; mã đoạn của chữ số 0..9: bit 0 = a, …, bit 6 = g\nled7    DB      3FH, 06H, 5BH, 4FH, 66H, 6DH, 7DH, 07H, 7FH, 6FH\nma      DB      2 DUP(?)                ; ma: chữ số 1, ma+1: chữ số 2\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = '0'..'9'\n; Viết code ở đây: đổi AL thành mã đoạn\n        MOV     ma, AL\n        MOV     AH, 08H\n        INT     21H\n; và ở đây\n        MOV     ma+1, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "12", "mem": [{"at": "ma", "bytes": [6, 91]}]}, {"in": "00", "mem": [{"at": "ma", "bytes": [63, 63]}]}, {"in": "89", "mem": [{"at": "ma", "bytes": [127, 111]}]}, {"in": "70", "mem": [{"at": "ma", "bytes": [7, 63]}]}, {"in": "45", "mem": [{"at": "ma", "bytes": [102, 109]}]}, {"in": "36", "mem": [{"at": "ma", "bytes": [79, 125]}]}]}, {"t": "Xoay vòng ba biến nhanh", "d": "Đọc ba phím vào ba biến byte a, b, c (code mẫu đã làm). Xoay vòng: a nhận giá trị cũ của c, b nhận giá trị cũ của a, c nhận giá trị cũ của b. Code mẫu đúng nhưng dùng 6 lệnh MOV và 3 thanh ghi. Viết lại phần xoay vòng bằng lệnh XCHG (bắt buộc: trang chấm kiểm mỗi test phải chạy ít nhất một lệnh XCHG; ghi thẳng phím vào vị trí đã xoay mà không dùng XCHG thì không đạt) để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: xoay vòng ba biến a ← c, b ← a, c ← b\n; Bản này đúng nhưng tốn: 6 lệnh MOV, 3 thanh ghi.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      ?\nb       DB      ?\nc       DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc 3 phím vào a, b, c\n        INT     21H\n        MOV     a, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     b, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     c, AL\n        MOV     AL, a                   ; xoay vòng (viết lại phần này)\n        MOV     BL, b\n        MOV     CL, c\n        MOV     b, AL                   ; b ← a\n        MOV     c, BL                   ; c ← b\n        MOV     a, CL                   ; a ← c\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABC", "mem": [{"at": "a", "bytes": [67]}, {"at": "b", "bytes": [65]}, {"at": "c", "bytes": [66]}]}, {"in": "123", "mem": [{"at": "a", "bytes": [51]}, {"at": "b", "bytes": [49]}, {"at": "c", "bytes": [50]}]}, {"in": "zzz", "mem": [{"at": "a", "bytes": [122]}, {"at": "b", "bytes": [122]}, {"at": "c", "bytes": [122]}]}, {"in": " ~!", "mem": [{"at": "a", "bytes": [33]}, {"at": "b", "bytes": [32]}, {"at": "c", "bytes": [126]}]}, {"in": "$aZ", "mem": [{"at": "a", "bytes": [90]}, {"at": "b", "bytes": [36]}, {"at": "c", "bytes": [97]}]}, {"in": "907", "mem": [{"at": "a", "bytes": [55]}, {"at": "b", "bytes": [57]}, {"at": "c", "bytes": [48]}]}], "perf": {"cycles": 326, "bytes": 46}, "require": ["XCHG"]}]);

makeQuiz("quiz13","score13",[{"q": "Lệnh nào dịch được trên 8086 (MASM, x và y là biến DW)?", "o": ["<code>MOV ES, AX<\/code>", "<code>MOV DS, 0714h<\/code>", "<code>MOV x, y<\/code>", "<code>MOV ES, DS<\/code>"], "a": 0, "e": "Thanh ghi đoạn chỉ nhận thanh ghi 16 bit hoặc word trong bộ nhớ. Không có dạng hằng → thanh ghi đoạn, đoạn → đoạn, và không có lệnh MOV với hai toán hạng bộ nhớ."}, {"q": "Biến n DW 5 ở độ lệch 0000h, so DW 0ABCDh ở độ lệch 0002h. Sau hai lệnh sau, BX và SI bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     BX, so\n        LEA     SI, so<\/pre>", "o": ["BX = 0002h, SI = ABCDh", "BX = ABCDh, SI = 0002h", "BX = ABCDh, SI = ABCDh", "BX = 0002h, SI = 0002h"], "a": 1, "e": "MOV với tên biến đọc nội dung (ABCDh); LEA đặt địa chỉ hiệu dụng của biến (0002h) và không đọc bộ nhớ (Ví dụ 6)."}, {"q": "Cần đổi chỗ hai biến word a và b. Cách nào dịch được và ngắn nhất?", "o": ["<code>XCHG a, b<\/code>", "<code>MOV AX, a<\/code> / <code>MOV a, b<\/code> / <code>MOV b, AX<\/code>", "<code>MOV AX, a<\/code> / <code>MOV BX, b<\/code> / <code>MOV a, BX<\/code> / <code>MOV b, AX<\/code>", "<code>MOV AX, a<\/code> / <code>XCHG AX, b<\/code> / <code>MOV a, AX<\/code>"], "a": 3, "e": "XCHG a, b và MOV a, b có hai toán hạng bộ nhớ nên không dịch được. Cách 4 lệnh MOV đúng nhưng 14 byte; cách MOV, XCHG, MOV chỉ 10 byte (mục 13.3)."}, {"q": "hex DB '0123456789ABCDEF'. Sau đoạn sau, AL bằng bao nhiêu?<pre class=\"mp-asm\">        LEA     BX, hex\n        MOV     AL, 0AH\n        XLAT<\/pre>", "o": ["0Ah, vì XLAT không đổi AL", "41h, mã ASCII của chữ A", "39h, mã ASCII của chữ số 9", "Địa chỉ BX + 0Ah của ô trong bảng"], "a": 1, "e": "XLAT thay AL bằng byte ở DS:[BX + AL] = hex[10] = 'A' = 41h. Chỉ số bắt đầu từ 0 nên hex[10] là ký tự thứ 11."}, {"q": "Cần nạp vào SI địa chỉ của biến bang (không có thanh ghi trong địa chỉ). Lệnh nào đúng và ít chu kỳ nhất?", "o": ["<code>MOV SI, OFFSET bang<\/code> (3 byte, 4 chu kỳ)", "<code>LEA SI, bang<\/code> (4 byte, 8 chu kỳ)", "<code>MOV SI, WORD PTR bang<\/code> (4 byte, 14 chu kỳ)", "<code>XCHG SI, WORD PTR bang<\/code> (4 byte, 23 chu kỳ)"], "a": 0, "e": "Địa chỉ của biến đơn là hằng biết lúc dịch, nên MOV SI, OFFSET bang (dạng thanh ghi ← số tức thời) nhanh nhất. LEA cũng đúng nhưng tốn 2 + EA. Hai lựa chọn còn lại đọc nội dung, không phải địa chỉ."}]);

